package com.rapidursa.shoulderpets;

final class EggState
{
    final int speciesId;
    final String speciesName;
    final int combatLevel;
    long remainingMillis;

    EggState(int speciesId, String speciesName, int combatLevel, long remainingMillis)
    {
        this.speciesId = speciesId;
        this.speciesName = speciesName;
        this.combatLevel = combatLevel;
        this.remainingMillis = remainingMillis;
    }

    String encode()
    {
        return "v2:" + speciesId + ":" + combatLevel + ":" + remainingMillis + ":" + speciesName.replace(":", "");
    }

    static EggState decode(String value)
    {
        boolean current = value.startsWith("v2:");
        String[] fields = (current ? value.substring(3) : value).split(":", 4);
        if (fields.length != 4) throw new IllegalArgumentException("Invalid egg state");
        long timer = Long.parseLong(fields[2]);
        // Old builds saved a wall-clock expiry. Preserve only its remaining time.
        if (!current && timer > 0) timer = Math.max(0, timer - System.currentTimeMillis());
        return new EggState(Integer.parseInt(fields[0]), fields[3], Integer.parseInt(fields[1]), timer);
    }
}

package com.rapidursa.shoulderpets;

import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemID;
import net.runelite.api.Model;
import net.runelite.api.ModelData;
import net.runelite.api.RuneLiteObject;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;

/** A purely local scene model. It never enters the server's ground-item list. */
final class GroundEgg
{
    private final Client client;
    private RuneLiteObject object;
    private WorldPoint location;

    GroundEgg(Client client) { this.client = client; }

    void show(WorldPoint where, PetTier tier)
    {
        if (where == null) return;
        if (object != null && where.equals(location)) return;
        clear();
        LocalPoint local = LocalPoint.fromWorld(client, where);
        if (local == null || where.getPlane() != client.getPlane()) return;
        ItemComposition item = client.getItemDefinition(itemId(tier));
        if (item == null) return;
        Model model;
        if (tier == PetTier.RARE)
        {
            ModelData data = client.loadModelData(item.getInventoryModel());
            if (data == null) return;
            data = data.cloneColors();
            short[] colors = data.getFaceColors();
            for (int i = 0; i < colors.length; i++)
            {
                int color = colors[i] & 0xffff;
                // Preserve shading and neutral details; tint coloured shell faces purple.
                if (((color >> 7) & 7) > 0)
                    colors[i] = (short) ((49 << 10) | (color & 1023));
            }
            model = data.light();
        }
        else model = client.loadModel(item.getInventoryModel());
        if (model == null) return;
        RuneLiteObject egg = client.createRuneLiteObject();
        egg.setModel(model);
        egg.setLocation(local, where.getPlane());
        egg.setActive(true);
        object = egg;
        location = where;
    }

    void clear()
    {
        if (object != null) object.setActive(false);
        object = null;
        location = null;
    }

    private static int itemId(PetTier tier)
    {
        switch (tier)
        {
            case UNCOMMON: return ItemID.BLUE_EGG;
            case RARE: return ItemID.BLUE_EGG;
            case EPIC: return ItemID.RED_EGG;
            case LEGENDARY: return ItemID.YELLOW_EGG;
            default: return ItemID.GREEN_EGG;
        }
    }
}

package com.rapidursa.shoulderpets;

import java.awt.image.BufferedImage;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Base64;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.stream.Collectors;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import net.runelite.api.Client;
import net.runelite.api.IndexDataBase;
import net.runelite.api.NPCComposition;

/** Incremental cache catalogue. Only requested, visible cards load model thumbnails. */
final class PetCatalogue
{
    static final class Entry
    {
        final String species;
        final int npcId, level;
        Entry(String species, int npcId, int level)
        { this.species = species; this.npcId = npcId; this.level = level; }
    }

    private final Map<String, Entry> entries = new ConcurrentHashMap<>();
    private final Map<String, BufferedImage> silhouettes = new ConcurrentHashMap<>();
    private final ArrayDeque<String> requests = new ArrayDeque<>();
    private final Set<String> queued = new HashSet<>();
    private final Map<String, Integer> retryAfter = new ConcurrentHashMap<>();
    private int[] ids;
    private int position, ticks;
    private volatile boolean complete;
    private int revision, indexFingerprint;
    private boolean needsSave;

    List<Entry> snapshot() { return new ArrayList<>(entries.values()); }
    boolean isComplete() { return complete; }
    BufferedImage silhouette(String species) { return silhouettes.get(species); }

    void restore(String saved)
    {
        if (saved == null || saved.length() > 5_000_000) return;
        try
        {
            String[] lines = saved.split("\n");
            String[] header = lines[0].split("\\|");
            if (header.length != 3 || !"1".equals(header[0])) return;
            int savedRevision = Integer.parseInt(header[1]);
            int savedFingerprint = Integer.parseInt(header[2]);
            Map<String, Entry> restored = new HashMap<>();
            for (int i = 1; i < lines.length; i++)
            {
                String[] fields = lines[i].split(":", 3);
                if (fields.length != 3) return;
                int id = Integer.parseInt(fields[0]), level = Integer.parseInt(fields[1]);
                String species = new String(Base64.getUrlDecoder().decode(fields[2]), StandardCharsets.UTF_8);
                if (id < 0 || level < 1 || species.isEmpty()) return;
                restored.put(species, new Entry(species, id, level));
            }
            if (restored.isEmpty()) return;
            entries.clear();
            entries.putAll(restored);
            revision = savedRevision;
            indexFingerprint = savedFingerprint;
            complete = true;
        }
        catch (IllegalArgumentException ex) { /* Rebuild a damaged or obsolete local catalogue. */ }
    }

    String consumeSave()
    {
        if (!needsSave) return null;
        needsSave = false;
        return "1|" + revision + "|" + indexFingerprint + "\n" + entries.values().stream()
            .sorted(java.util.Comparator.comparing(e -> e.species))
            .map(e -> e.npcId + ":" + e.level + ":" + Base64.getUrlEncoder().withoutPadding()
                .encodeToString(e.species.getBytes(StandardCharsets.UTF_8)))
            .collect(Collectors.joining("\n"));
    }

    void request(String species)
    {
        if (!silhouettes.containsKey(species) && ticks >= retryAfter.getOrDefault(species, 0)
            && queued.add(species)) requests.add(species);
    }

    boolean tick(Client client)
    {
        ticks++;
        boolean changed = false;
        if (ids == null)
        {
            IndexDataBase cache = client.getIndexConfig();
            if (cache == null) return false;
            ids = cache.getFileIds(9); // NPC definitions archive.
            if (ids == null) return false;
            int currentRevision = client.getRevision();
            int fingerprint = Arrays.hashCode(ids);
            if (complete && revision == currentRevision && indexFingerprint == fingerprint)
                position = ids.length;
            else if (complete)
            {
                entries.clear();
                silhouettes.clear();
                requests.clear();
                queued.clear();
                retryAfter.clear();
                complete = false;
                changed = true;
            }
            revision = currentRevision;
            indexFingerprint = fingerprint;
        }
        long deadline = System.nanoTime() + 3_000_000;
        for (int batch = 0; position < ids.length && batch < 100; batch++)
        {
            NPCComposition npc = client.getNpcDefinition(ids[position++]);
            if (npc != null && eligible(npc))
            {
                String species = npc.getName().trim().toLowerCase(Locale.ROOT).replace(';', ' ');
                Entry previous = entries.get(species);
                // Match the existing one-unlock-per-name collection; use the lowest-level variant.
                if (previous == null || npc.getCombatLevel() < previous.level)
                {
                    entries.put(species, new Entry(species, npc.getId(), npc.getCombatLevel()));
                    silhouettes.remove(species);
                    changed = true;
                }
            }
            if (System.nanoTime() >= deadline) break;
        }
        if (!complete && position == ids.length) { complete = true; needsSave = true; changed = true; }
        for (int built = 0; built < 2 && !requests.isEmpty(); built++)
        {
            String species = requests.remove();
            queued.remove(species);
            Entry entry = entries.get(species);
            if (entry == null || silhouettes.containsKey(species)) continue;
            BufferedImage preview = PetPreview.build(client, entry.npcId);
            if (preview == null) { retryAfter.put(species, ticks + 10); continue; }
            silhouettes.put(species, toSilhouette(preview));
            changed = true;
        }
        return changed;
    }

    private static boolean eligible(NPCComposition npc)
    {
        String name = npc.getName();
        if (name == null || name.trim().isEmpty() || "null".equalsIgnoreCase(name)
            || npc.getCombatLevel() < 1 || npc.getModels() == null) return false;
        String[] actions = npc.getActions();
        if (actions != null) for (String action : actions)
            if ("Attack".equalsIgnoreCase(action)) return true;
        return false;
    }

    static BufferedImage toSilhouette(BufferedImage source)
    {
        BufferedImage image = new BufferedImage(source.getWidth(), source.getHeight(), BufferedImage.TYPE_INT_ARGB);
        for (int y = 0; y < image.getHeight(); y++) for (int x = 0; x < image.getWidth(); x++)
            image.setRGB(x, y, (source.getRGB(x, y) & 0xff000000) | 0x666666);
        return image;
    }
}

package com.rapidursa.shoulderpets;

final class PetPlacement
{
    final int sideways, height, forward, size;

    PetPlacement(int sideways, int height, int forward, int size)
    {
        this.sideways = Math.max(-256, Math.min(256, sideways));
        this.height = Math.max(-256, Math.min(256, height));
        this.forward = Math.max(-256, Math.min(256, forward));
        this.size = Math.max(10, Math.min(100, size));
    }

    static PetPlacement defaults() { return new PetPlacement(42, 0, 0, 20); }

    String encode() { return sideways + "," + height + "," + forward + "," + size; }

    static PetPlacement decode(String value)
    {
        if (value == null) return null;
        String[] fields = value.split(",");
        if (fields.length != 4) return null;
        try
        {
            return new PetPlacement(Integer.parseInt(fields[0]), Integer.parseInt(fields[1]),
                Integer.parseInt(fields[2]), Integer.parseInt(fields[3]));
        }
        catch (NumberFormatException ex) { return null; }
    }
}

package com.rapidursa.shoulderpets;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.ModelData;
import net.runelite.api.NPCComposition;

/** Small static model thumbnails rendered offscreen without changing RuneLite's rasterizer. */
final class PetPreview
{
    private PetPreview() { }

    static BufferedImage build(Client client, int npcId)
    {
        NPCComposition npc = client.getNpcDefinition(npcId);
        if (npc == null || npc.getModels() == null) return null;
        List<ModelData> parts = new ArrayList<>();
        for (int id : npc.getModels())
        {
            if (id < 0) continue;
            ModelData part = client.loadModelData(id);
            if (part != null) parts.add(part);
            else return null; // Wait until all model parts are in the cache.
        }
        if (parts.isEmpty()) return null;
        ModelData data = parts.size() == 1 ? parts.get(0) : client.mergeModels(parts.toArray(new ModelData[0]));
        if (data == null) return null;
        short[] from = npc.getColorToReplace(), to = npc.getColorToReplaceWith();
        if (from != null && to != null)
        {
            data = data.cloneColors();
            for (int i = 0; i < Math.min(from.length, to.length); i++) data.recolor(from[i], to[i]);
        }
        Model model = data.light(64, 768, -50, -10, -50);
        return draw(model);
    }

    static BufferedImage draw(Model model)
    {
        int count = model.getVerticesCount();
        if (count == 0 || model.getFaceCount() == 0) return null;
        float[] vx = model.getVerticesX(), vy = model.getVerticesY(), vz = model.getVerticesZ();
        double[] x = new double[count], y = new double[count], depth = new double[count];
        double yaw = Math.toRadians(-25), pitch = Math.toRadians(12);
        double minX = Double.POSITIVE_INFINITY, maxX = Double.NEGATIVE_INFINITY;
        double minY = Double.POSITIVE_INFINITY, maxY = Double.NEGATIVE_INFINITY;
        for (int i = 0; i < count; i++)
        {
            x[i] = vx[i] * Math.cos(yaw) + vz[i] * Math.sin(yaw);
            double z = vz[i] * Math.cos(yaw) - vx[i] * Math.sin(yaw);
            y[i] = vy[i] * Math.cos(pitch) - z * Math.sin(pitch);
            depth[i] = z * Math.cos(pitch) + vy[i] * Math.sin(pitch);
            minX = Math.min(minX, x[i]); maxX = Math.max(maxX, x[i]);
            minY = Math.min(minY, y[i]); maxY = Math.max(maxY, y[i]);
        }
        int[] a = model.getFaceIndices1(), b = model.getFaceIndices2(), c = model.getFaceIndices3();
        int[] firstColors = model.getFaceColors1(), secondColors = model.getFaceColors2(), thirdColors = model.getFaceColors3();
        byte[] transparency = model.getFaceTransparencies();
        List<Integer> faces = new ArrayList<>();
        for (int f = 0; f < model.getFaceCount(); f++) faces.add(f);
        faces.sort(Comparator.comparingDouble((Integer f) ->
            (depth[a[f]] + depth[b[f]] + depth[c[f]]) / 3).reversed());
        BufferedImage image = new BufferedImage(64, 64, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = image.createGraphics();
        try
        {
            g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            double scale = Math.min(56 / Math.max(1, maxX - minX), 56 / Math.max(1, maxY - minY));
            double centerX = (minX + maxX) / 2, centerY = (minY + maxY) / 2;
            for (int f : faces)
            {
                if (thirdColors[f] == -2) continue;
                int alpha = transparency == null ? 255 : 255 - (transparency[f] & 255);
                if (alpha == 0) continue;
                Color color = hsl(firstColors[f]);
                if (thirdColors[f] >= 0)
                {
                    Color other = hsl(secondColors[f]), last = hsl(thirdColors[f]);
                    color = new Color((color.getRed() + other.getRed() + last.getRed()) / 3,
                        (color.getGreen() + other.getGreen() + last.getGreen()) / 3,
                        (color.getBlue() + other.getBlue() + last.getBlue()) / 3);
                }
                g.setColor(new Color(color.getRed(), color.getGreen(), color.getBlue(), alpha));
                Polygon polygon = new Polygon();
                for (int vertex : new int[] { a[f], b[f], c[f] })
                    polygon.addPoint((int) Math.round(32 + (x[vertex] - centerX) * scale),
                        (int) Math.round(32 + (y[vertex] - centerY) * scale));
                g.fillPolygon(polygon);
            }
        }
        finally { g.dispose(); }
        return image;
    }

    private static Color hsl(int packed)
    {
        double hue = ((packed >> 10) & 63) / 64.0 + 1.0 / 128;
        double saturation = ((packed >> 7) & 7) / 8.0 + 1.0 / 16;
        double lightness = (packed & 127) / 128.0;
        double chroma = (1 - Math.abs(2 * lightness - 1)) * saturation;
        double h = hue * 6, x = chroma * (1 - Math.abs(h % 2 - 1));
        double r = 0, g = 0, b = 0;
        if (h < 1) { r = chroma; g = x; }
        else if (h < 2) { r = x; g = chroma; }
        else if (h < 3) { g = chroma; b = x; }
        else if (h < 4) { g = x; b = chroma; }
        else if (h < 5) { r = x; b = chroma; }
        else { r = chroma; b = x; }
        double m = lightness - chroma / 2;
        return new Color(channel(r + m), channel(g + m), channel(b + m));
    }

    private static int channel(double value) { return Math.max(0, Math.min(255, (int) Math.round(value * 255))); }
}

package com.rapidursa.shoulderpets;

import java.awt.Color;
import java.time.Duration;

enum PetTier
{
    COMMON(1, 50, 150, 1, new Color(74, 172, 79)),
    UNCOMMON(50, 100, 125, 3, new Color(70, 145, 233)),
    RARE(100, 200, 100, 10, new Color(180, 95, 228)),
    EPIC(200, 500, 50, 15, new Color(217, 72, 64)),
    LEGENDARY(500, Integer.MAX_VALUE, 25, 24, new Color(244, 203, 76));

    final int minimum;
    final int maximumExclusive;
    final int denominator;
    final Duration hatchTime;
    final Color color;

    PetTier(int minimum, int maximumExclusive, int denominator, int hours, Color color)
    {
        this.minimum = minimum;
        this.maximumExclusive = maximumExclusive;
        this.denominator = denominator;
        this.hatchTime = Duration.ofHours(hours);
        this.color = color;
    }

    static PetTier forLevel(int combatLevel)
    {
        for (PetTier tier : values())
        {
            if (combatLevel >= tier.minimum && combatLevel < tier.maximumExclusive) return tier;
        }
        return COMMON;
    }

    String label()
    {
        return name().charAt(0) + name().substring(1).toLowerCase();
    }
}

package com.rapidursa.shoulderpets;

import java.util.ArrayList;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.ModelData;
import net.runelite.api.NPCComposition;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.RuneLiteObject;
import net.runelite.api.coords.LocalPoint;

/** A micro pet sharing the player's tile, with a small local offset beside them. */
final class ShoulderPetRenderer
{
    private final Client client;
    private final ShoulderPetsConfig config;
    private MicroObject object;
    private int npcId = -1;
    private int size;
    private int animationId = Integer.MIN_VALUE;
    private int lastX, lastY;
    private long movingUntil;

    ShoulderPetRenderer(Client client, ShoulderPetsConfig config)
    {
        this.client = client;
        this.config = config;
    }

    void update(Player player, int selectedNpcId, int idleAnimation, int walkAnimation)
    {
        if (player == null || selectedNpcId < 0 || player.getLocalLocation() == null)
        {
            clear();
            return;
        }
        int newSize = Math.max(10, Math.min(100, config.shoulderSize()));
        if (object == null || npcId != selectedNpcId || size != newSize)
        {
            clear();
            object = build(selectedNpcId, newSize);
            if (object == null) return;
            npcId = selectedNpcId;
            size = newSize;
            lastX = player.getLocalLocation().getX();
            lastY = player.getLocalLocation().getY();
        }
        LocalPoint playerPoint = player.getLocalLocation();
        long now = System.currentTimeMillis();
        if (playerPoint.getX() != lastX || playerPoint.getY() != lastY) movingUntil = now + 180;
        lastX = playerPoint.getX();
        lastY = playerPoint.getY();
        int nextAnimation = now < movingUntil && walkAnimation >= 0 ? walkAnimation : idleAnimation;
        if (nextAnimation != animationId)
        {
            object.setAnimation(nextAnimation >= 0 ? client.loadAnimation(nextAnimation) : null);
            object.setShouldLoop(true);
            animationId = nextAnimation;
        }
        // Rotate the sideways/forward offsets with the player's facing direction.
        int orientation = player.getCurrentOrientation();
        double angle = orientation * Math.PI / 1024.0;
        int side = Math.max(-256, Math.min(256, config.shoulderSide()));
        int forward = Math.max(-256, Math.min(256, config.shoulderForward()));
        int dx = (int) Math.round(side * Math.cos(angle) + forward * Math.sin(angle));
        int dy = (int) Math.round(forward * Math.cos(angle) - side * Math.sin(angle));
        LocalPoint point = new LocalPoint(playerPoint.getX() + dx, playerPoint.getY() + dy, playerPoint.getWorldView());
        int plane = player.getWorldLocation().getPlane();
        object.setLocation(point, plane);
        object.setZ(Perspective.getTileHeight(client, playerPoint, plane)
            + Math.max(-256, Math.min(256, config.shoulderHeight())));
        object.setOrientation(orientation);
        if (!object.isActive()) object.setActive(true);
    }

    void clear()
    {
        if (object != null) object.setActive(false);
        object = null;
        npcId = -1;
        animationId = Integer.MIN_VALUE;
        movingUntil = 0;
    }

    private MicroObject build(int id, int size)
    {
        NPCComposition npc = client.getNpcDefinition(id);
        if (npc == null || npc.getModels() == null) return null;
        List<ModelData> parts = new ArrayList<>();
        for (int modelId : npc.getModels())
        {
            if (modelId < 0) continue;
            ModelData part = client.loadModelData(modelId);
            if (part != null) parts.add(part);
        }
        if (parts.isEmpty()) return null;
        ModelData data = parts.size() == 1 ? parts.get(0) : client.mergeModels(parts.toArray(new ModelData[0]));
        if (data == null) return null;
        short[] oldColors = npc.getColorToReplace();
        short[] newColors = npc.getColorToReplaceWith();
        if (oldColors != null && newColors != null)
        {
            data = data.cloneColors();
            for (int i = 0; i < Math.min(oldColors.length, newColors.length); i++)
                data.recolor(oldColors[i], newColors[i]);
        }
        // Animate the full-sized model first, then shrink it, so animation translations scale too.
        Model base = data.light(64, 768, -50, -10, -50);
        Model staticModel = data.cloneVertices().scale(Math.round(128f * size / 100),
            Math.round(128f * size / 100), Math.round(128f * size / 100)).light(64, 768, -50, -10, -50);
        MicroObject pet = new MicroObject(client, size, staticModel);
        pet.setModel(base);
        return pet;
    }

    private static final class MicroObject extends RuneLiteObject
    {
        private final int scale;
        private final Model staticModel;

        MicroObject(Client client, int size, Model staticModel)
        {
            super(client);
            this.scale = Math.round(128f * size / 100);
            this.staticModel = staticModel;
        }

        @Override public Model getModel()
        {
            if (getAnimationController() == null) return staticModel;
            Model model = super.getModel();
            if (model == null) return null;
            model.scale(scale, scale, scale);
            model.calculateBoundsCylinder();
            return model;
        }
    }
}

package com.rapidursa.shoulderpets;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup("rapidShoulderPets")
public interface ShoulderPetsConfig extends Config
{
    @ConfigItem(keyName = "showTimer", name = "Show egg timer", description = "Show the current egg and hatch countdown")
    default boolean showTimer() { return true; }

    @Range(min = -256, max = 256)
    @ConfigItem(keyName = "shoulderSide", name = "Pet sideways", description = "Move the active pet left/right; saved separately for this species")
    default int shoulderSide() { return 42; }

    @Range(min = -256, max = 256)
    @ConfigItem(keyName = "shoulderHeight", name = "Pet height", description = "Active pet height; negative is up; saved separately for this species")
    default int shoulderHeight() { return 0; }

    @Range(min = -256, max = 256)
    @ConfigItem(keyName = "shoulderForward", name = "Pet forward", description = "Move active pet forward/back; saved separately for this species")
    default int shoulderForward() { return 0; }

    @Range(min = 10, max = 100)
    @ConfigItem(keyName = "shoulderSize", name = "Pet size %", description = "Scale active pet, 10 to 100 percent; saved separately for this species")
    default int shoulderSize() { return 20; }
}

package com.rapidursa.shoulderpets;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.time.Duration;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayMenuEntry;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.ImageComponent;
import net.runelite.client.ui.overlay.components.PanelComponent;
import net.runelite.api.MenuAction;

public class ShoulderPetsOverlay extends Overlay
{
    private final ShoulderPetsPlugin plugin;
    private final ShoulderPetsConfig config;
    private final PanelComponent panel = new PanelComponent();

    @Inject ShoulderPetsOverlay(ShoulderPetsPlugin plugin, ShoulderPetsConfig config)
    {
        this.plugin = plugin;
        this.config = config;
        setPosition(OverlayPosition.TOP_LEFT);
        getMenuEntries().add(new OverlayMenuEntry(MenuAction.RUNELITE_OVERLAY, "Hatch egg", "Rapid Pets"));
    }

    @Override public Dimension render(Graphics2D graphics)
    {
        if (!config.showTimer()) return null;
        EggState egg = plugin.getEgg();
        if (egg == null) return null;
        panel.getChildren().clear();
        PetTier tier = PetTier.forLevel(egg.combatLevel);
        panel.getChildren().add(new ImageComponent(createEggIcon(tier.color)));
        long remaining = Math.max(0, egg.remainingMillis);
        Duration time = Duration.ofMillis(remaining);
        String label = remaining == 0 ? "Ready! Right click to hatch" :
            String.format("%dh %02dm %02ds", time.toHours(), time.toMinutes() % 60, time.getSeconds() % 60);
        panel.getChildren().add(LineComponent.builder().left(egg.speciesName + " egg").leftColor(tier.color).build());
        panel.getChildren().add(LineComponent.builder().left(label).build());
        return panel.render(graphics);
    }

    static BufferedImage createEggIcon(Color shell)
    {
        BufferedImage icon = new BufferedImage(32, 38, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = icon.createGraphics();
        try
        {
            g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g.setColor(new Color(75, 46, 25));
            g.fillOval(4, 5, 24, 32);
            g.setColor(shell);
            g.fillOval(6, 6, 20, 28);
            g.setColor(new Color(255, 255, 255, 115));
            g.fillOval(9, 9, 8, 12);
            g.setColor(new Color(35, 20, 20, 100));
            g.fillOval(19, 24, 3, 3);
        }
        finally { g.dispose(); }
        return icon;
    }
}

package com.rapidursa.shoulderpets;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.GridLayout;
